/**
 * The Fugitive Friar — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { FUGITIVE_FRIAR_TEMPLATE } from '../fugitive-friar';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Fugitive Friar — template structure", () => {
  it('carries its identity', () => {
    expect(FUGITIVE_FRIAR_TEMPLATE.id).toBe('encounter.town.fugitive_friar');
    expect(FUGITIVE_FRIAR_TEMPLATE.reach).toBe('shadow');
    expect(FUGITIVE_FRIAR_TEMPLATE.rarityTier).toBe(2);
    expect(FUGITIVE_FRIAR_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = FUGITIVE_FRIAR_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['friar.show_the_way_out', 'friar.slow_the_pulse']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['life', 'mind']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(FUGITIVE_FRIAR_TEMPLATE.settings).toEqual(['urban']);
    expect(FUGITIVE_FRIAR_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(FUGITIVE_FRIAR_TEMPLATE.consequenceDraw).toEqual(['possession', 'membership']);
    expect(FUGITIVE_FRIAR_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.fugitive_friar',
          reach: 'shadow',
          rarityTier: 2,
        }),
        FUGITIVE_FRIAR_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
